/**
 * Reveal images (FR-18 phase three) — the moment a hidden thing is
 * shown to the table.
 *
 * The image itself is generated by Muse on the fly (an image model,
 * from a prompt this module builds) and uploaded with the existing
 * uploader (`src/worldbuilding/upload.ts`); this module only handles
 * the prompt, the validation, and the chat post. It never generates
 * an image and never touches Foundry.
 *
 * Two delivery modes, one step:
 *   - "chat": the image posts inline in a chat message (an <img> in
 *     the message HTML — Foundry renders it in the chat log).
 *   - "popout": the nicer screen popup. NOT reachable from the MCP
 *     path — opening client UI needs a client-side module, which does
 *     not exist yet. A popout step is accepted by validation but the
 *     live handler falls back to the chat post and says so in the step
 *     result, so a script never silently pretends a popup happened.
 *
 * Verified vs live: the prompt builder, the validation, and the HTML
 * are pure and unit-tested here. Whether Foundry renders the inline
 * <img> in chat the way the table expects — and whether the image URL
 * (worlds/testbed/...) resolves for every client — needs a live
 * session (see BACKLOG FR-18).
 */
export type RevealMode = "chat" | "popout";

export interface RevealStepInput {
  kind: "reveal";
  what?: "image";
  image?: unknown;
  caption?: unknown;
  mode?: unknown;
  alias?: unknown;
  sceneId?: unknown;
}

/** What the prompt is grounded in: the room, the corpse, the creature. */
export interface RevealScene {
  /** Room name, e.g. "Lich's Lair — Entry Hall". */
  name: string;
  /** One line of room description, e.g. "torch-lit stone hall". */
  description?: string;
}

export interface RevealEvent {
  /** The creature emerging, e.g. "a thick, pale tentacle". */
  creature: string;
  /** The corpse it comes out of, e.g. "the dead ogre". */
  corpse: string;
  /** What happens, e.g. "rips upward through its stomach". */
  action: string;
}

/**
 * Build the image prompt for a reveal, grounded in the fiction: the
 * room, the corpse on the floor, the creature. No generic gore — the
 * prompt names the specific nouns (room, corpse, creature) instead of
 * asking for blood and horror in the abstract.
 */
export function buildRevealPrompt(scene: RevealScene, event: RevealEvent): string {
  const room = scene.description
    ? `${scene.name} — ${scene.description}`
    : scene.name;
  return (
    `Top-down view inside a torch-lit stone dungeon room, ${room}. ` +
    `On the floor lies the corpse of ${event.corpse}, sprawled where it fell. ` +
    `${event.creature} ${event.action}, coiling toward the ceiling. ` +
    `Cold torchlight, deep shadows, dungeon-crawl atmosphere, painterly. No text, no labels.`
  );
}

/** Escape text for embedding in chat HTML. */
export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/**
 * The chat message HTML for an image reveal: the image inline, the
 * caption under it when given. Foundry renders HTML in chat message
 * content, so the <img> shows in the log.
 */
export function revealImageChatHtml(imageUrl: string, caption?: string): string {
  const img = `<img src="${escapeHtml(imageUrl)}" style="max-width:100%; border-radius:6px;" />`;
  if (!caption) return img;
  return `${img}<p style="margin:4px 0 0;">${escapeHtml(caption)}</p>`;
}

/**
 * Validate a reveal-image step (the `{kind: "reveal", image, ...}`
 * shape, with or without `what: "image"`). Returns every error found.
 */
export function validateReveal(
  step: RevealStepInput,
): { ok: true } | { ok: false; errors: string[] } {
  const errors: string[] = [];
  if (typeof step.image !== "string" || step.image.length === 0) {
    errors.push(`reveal (image): "image" must be a non-empty string (the uploaded image path).`);
  }
  if (
    step.mode !== undefined &&
    step.mode !== "chat" &&
    step.mode !== "popout"
  ) {
    errors.push(
      `reveal (image): "mode" must be "chat" or "popout", got ${JSON.stringify(step.mode)}.`,
    );
  }
  if (step.caption !== undefined && typeof step.caption !== "string") {
    errors.push(`reveal (image): "caption" must be a string.`);
  }
  if (step.alias !== undefined && (typeof step.alias !== "string" || step.alias.length === 0)) {
    errors.push(`reveal (image): "alias" must be a non-empty string when present.`);
  }
  if (errors.length > 0) return { ok: false, errors };
  return { ok: true };
}
